#pragma once
// The character questions laya's Python reference answers with str.isalpha(), str.lower(), re's
// \w and friends. Every predicate is a table recorded from CPython (kVersion), generated by
// laya-go/scripts/gen_tables.py --lang cpp, so every compiler and OS gives one answer. Strings are
// UTF-8 bytes; bytes that are not valid UTF-8 decode as Go's range loop does, one U+FFFD per byte.
#include <cstdint>
#include <string>
#include <string_view>
#include <vector>

namespace laya {
namespace unicodedata {

extern const char* const kVersion;  // the Unicode release of the tables, e.g. "15.0.0"
constexpr char32_t kReplacement = 0xFFFD;

bool IsAlpha(char32_t r);     // str.isalpha()
bool IsWord(char32_t r);      // [^\W\d_]
bool IsCombining(char32_t r); // non-zero canonical combining class
bool IsDigit(char32_t r);     // \d (Nd)
bool IsUpper(char32_t r);
bool IsLower(char32_t r);
bool IsSpace(char32_t r);
bool IsMark(char32_t r);      // Mn, Mc, Me
bool IsInitial(char32_t r);   // Lu, Lt, Lo
bool IsPrintable(char32_t r);
bool IsPythonWord(char32_t r);   // \w
bool IsWordOrDigit(char32_t r);  // [^\W_]
bool IsUpperString(std::string_view s);  // str.isupper()

// UTF-8 helpers with Go's semantics: an invalid sequence is (kReplacement, width 1).
struct Decoded {
  char32_t rune;
  size_t width;
};
Decoded DecodeRune(std::string_view s);      // first rune; s must be non-empty
Decoded DecodeLastRune(std::string_view s);  // last rune; s must be non-empty
bool ValidUtf8(std::string_view s);
void AppendRune(std::string& out, char32_t r);  // invalid scalar values append U+FFFD
size_t RuneCount(std::string_view s);

char32_t LowerRune(char32_t r);
std::string Lower(std::string_view s);        // str.lower(), final sigma included
std::string Lossy(std::string_view bytes);    // bytes.decode("utf-8", "replace")
std::string ToValid(std::string_view s);      // same as Lossy; no copy needed when valid is the caller's job
std::string DecimalASCII(std::string_view s);
std::string Strip(std::string_view s);        // str.strip()
std::string StripNumeric(std::string_view s);
bool IsBlank(std::string_view s);
std::vector<std::string> Fields(std::string_view s);  // str.split()

}  // namespace unicodedata
}  // namespace laya
